import { create_list_edit_delete_splay_questions } from "@/graphql/mutations";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "../SnackBar.vue";
export default {
  props: {
    DialogCreateQuestion: Boolean,
    StoreObj: Object
  },
  components: {
    SnackBar
  },
  data: () => ({
    question: "",
    optionOne: "",
    optiontwo: "",
    optionThree: "",
    optionFour: "",
    answer: "",
    loading: false,
    correctOption: null,
    SnackBarComponent: {}
  }),
  watch: {
    DialogCreateQuestion(val) {
      if (!val) {
        this.$refs.form.reset();
        this.correctOption = null;
      }
    }
  },
  methods: {
    async ValidateForm() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.CreateQuestion();
      }
    },
    async CreateQuestion() {
      this.loading = true;
      try {
        const result = await API.graphql(graphqlOperation(create_list_edit_delete_splay_questions, {
          input: {
            action_type: "CREATE",
            splay_category_id: this.StoreObj.splay_category_id,
            splay_question_text: this.question,
            splay_option_1: this.optionOne,
            splay_option_2: this.optiontwo,
            splay_option_3: this.optionThree,
            splay_option_4: this.optionFour,
            splay_correct_option: this.answer = this.correctOption === 1 ? this.optionOne : this.correctOption === 2 ? this.optiontwo : this.correctOption === 3 ? this.optionThree : this.correctOption === 4 ? this.optionFour : ""
          }
        }));
        let resultObj = JSON.parse(result.data.create_list_edit_delete_splay_questions);
        if (resultObj && resultObj.Status === "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: resultObj.Message
          };
        }
        this.loading = false;
        this.DialogCreateQuestionEmit(2);
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Failed to create question, try again"
        };
      }
      this.loading = false;
    },
    DialogCreateQuestionEmit(Toggle) {
      this.$emit("clicked", Toggle);
    }
  }
};
